/* Spa Motos 20IVI - aplicación (interfaz). Los datos y la autenticación los resuelven js/runtime.js y js/backend.js */
const LG={l:'assets/logo-light.png',d:'assets/logo-dark.png',i:'assets/icon.png'};

const $=s=>document.querySelector(s), COP=n=>'$'+Math.round(n).toLocaleString('es-CO');
const DEF={services:[
{id:'gen',ic:'🫧',name:'Lavado general',d:'Jabón, enjuague y secado completo.',price:15000,min:30},
{id:'pro',ic:'⚡',name:'Lavado pro',d:'General + cadena, rines y plásticos detallados.',price:25000,min:60},
{id:'adv',ic:'👑',name:'Lavado avanzado',d:'Pro + motor, brillo y acabado de exhibición.',price:40000,min:90},
{id:'cas',ic:'🪖',name:'Lavado de casco',d:'Exterior, interior y desinfección.',price:8000,min:30},
{id:'des',ic:'🛢️',name:'Desengrasado',d:'Quita grasa de motor, cadena y chasis.',price:12000,min:30},
{id:'cad',ic:'⛓️',name:'Cadena y lubricación',d:'Limpieza profunda y lubricante nuevo.',price:10000,min:30},
{id:'enc',ic:'✨',name:'Encerado',d:'Cera protectora con brillo duradero.',price:20000,min:30},
{id:'pla',ic:'🧴',name:'Restaurar plásticos',d:'Devuelve el color a plásticos opacos.',price:15000,min:30},
{id:'cer',ic:'💎',name:'Protección cerámica',d:'Capa protectora de larga duración.',price:60000,min:90}],
pm:[{n:'Efectivo',d:''},{n:'Nequi',d:''},{n:'Daviplata',d:''},{n:'Transferencia',d:''}],set:{wa:'',addr:'',ally:10,code:'ALIADO'},combos:[{n:'Combo Brillo',ids:['pro','cas'],pct:10},{n:'Spa Total',ids:['adv','enc','cad'],pct:15}],staff:[{id:'s1',name:'Camilo'},{id:'s2',name:'Andrés'},{id:'s3',name:'Dani'}]};
let cfg=JSON.parse(JSON.stringify(DEF)),db=null,user=null,isAdmin=false,unsub=[];
const S={page:'reserva',step:0,sel:new Set(),staff:null,date:null,slot:null,taken:new Set(),f:{name:'',phone:'',moto:''},done:null,tab:'agenda',adate:null,books:[]};
const ymd=d=>d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
const days=[...Array(14)].map((_,i)=>{const d=new Date();d.setDate(d.getDate()+i);return d});
S.date=ymd(days[0]);S.adate=S.date;
const lab=i=>{const m=480+i*30;return String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0')};
const N=20, DN=['dom','lun','mar','mié','jue','vie','sáb'];
const base=()=>cfg.services.filter(s=>S.sel.has(s.id)).reduce((a,s)=>a+s.price,0);
const disc=()=>{let d=0;(cfg.combos||[]).forEach(c=>{if(c.ids.every(i=>S.sel.has(i)))d+=c.pct/100*cfg.services.filter(s=>c.ids.includes(s.id)).reduce((a,s)=>a+s.price,0)});if(S.ok)d+=(base()-d)*(+cfg.set.ally||0)/100;if(S.cdisc)d+=(base()-d)*S.cdisc/100;return d};
const tot=()=>base()-disc();
const mins=()=>cfg.services.filter(s=>S.sel.has(s.id)).reduce((a,s)=>a+s.min,0);
const need=()=>Math.max(1,Math.ceil(mins()/30));
const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
function free(i){ if(S.staff==null)return false; const n=need(); if(i+n>N)return false;
 const now=new Date(); if(S.date===ymd(now)&&480+i*30<now.getHours()*60+now.getMinutes())return false;
 for(let k=0;k<n;k++)if(S.taken.has(S.staff+'_'+(i+k)))return false; return true;}
let uB=()=>{};function watchSlots(){unsub.forEach(u=>u());unsub=[]; if(!db)return;
 unsub.push(db.collection('slots').where('date','==',S.date).onSnapshot(q=>{S.taken=new Set(q.docs.map(d=>{const x=d.data();return x.staff+'_'+x.i}));S.blk=new Set(q.docs.filter(d=>d.data().bid==='blk').map(d=>{const x=d.data();return x.staff+'_'+x.i}));if(!S.done)render()},()=>{}));}
function watchBooks(){if(!db||!isAdmin)return;uB();
 uB=(db.collection('bookings').onSnapshot(q=>{S.all=q.docs.map(d=>d.data());S.books=S.all.filter(b=>b.date===S.adate).sort((a,b)=>a.start-b.start);if(isAdminView())render()},()=>{S.books=null;if(isAdminView())render()}));}
const isAdminView=()=>location.hash==='#admin';
const saveCfg=()=>window.saveC&&saveC();
async function confirmBooking(){const n=need(),id='b'+Date.now().toString(36);
 const svc=cfg.services.filter(s=>S.sel.has(s.id)).map(s=>s.name);
 const b={id,date:S.date,staff:S.staff,start:S.slot,n,svc,total:tot(),...S.f,cd:S.cdisc||0,st:'pend',created:Date.now()};
 if(db){try{await Promise.all([db.collection('bookings').doc(id).set(b),...[...Array(n)].map((_,k)=>db.collection('slots').doc(id+'_'+k).set({date:S.date,staff:S.staff,i:S.slot+k,bid:id}))])}catch(e){alert('No se pudo guardar la cita. Intenta de nuevo.');return}}
 S.done=b;render();}
async function cancelBooking(b){if(!db||!confirm('¿Cancelar la cita de '+b.name+'?'))return;
 await Promise.all([db.collection('bookings').doc(b.id).delete(),...[...Array(b.n)].map((_,k)=>db.collection('slots').doc(b.id+'_'+k).delete())]);}
const sName=id=>(cfg.staff.find(s=>s.id===id)||{name:'—'}).name;
function head(){return `<nav><div class="logo">SPA MOTOS <b>20IVI</b></div>${isAdmin?`<button class="pill" onclick="location.hash=isAdminView()?'':'#admin'">${isAdminView()?'← Ver como cliente':'⚙ Admin'}</button>`:''}</nav>${isAdminView()?'':tabsHtml()}`}
function render(){const a=$('#app'),bar=$('#bar');
 if(isAdminView())return renderAdmin(a,bar);
 if(S.page!=='reserva'){bar.hidden=true;a.innerHTML=head()+pages();return}
 bar.hidden=!!S.done;
 if(S.done){const b=S.done;bar.hidden=true;a.innerHTML=head()+`<div class="done"><div class="big">🏍️</div><h1 style="font-size:64px">¡Listo, ${esc(b.name.split(' ')[0])}!</h1><p style="color:var(--mut)">Tu moto tiene cita. Te esperamos.</p><div class="ticket"><div><span>Fecha</span><b>${b.date}</b></div><div><span>Hora</span><b>${lab(b.start)}</b></div><div><span>Atiende</span><b>${esc(sName(b.staff))}</b></div><div><span>Servicios</span><b style="text-align:right">${b.svc.map(esc).join('<br>')}</b></div><div><span>Total</span><b style="color:var(--ac)">${COP(b.total)}</b></div></div>${cfg.set.wa?`<a class="btn" style="display:inline-block;text-decoration:none;background:#25d366;margin-right:8px" target="_blank" href="https://wa.me/${cfg.set.wa}?text=${encodeURIComponent('Hola, soy '+b.name+'. Agendé '+b.svc.join(', ')+' el '+b.date+' a las '+lab(b.start)+' con '+sName(b.staff)+'. Total '+COP(b.total))}">Confirmar por WhatsApp</a>`:''}<button class="btn" onclick="location.reload()">Agendar otra</button></div>`;return}
 let h=head();
 if(S.step===0)h+=`<div class="hero"><div class="wheel"></div><h1>Tu moto<span>merece spa.</span></h1><p>Elige tus servicios, escoge quién la lava y reserva tu hora en menos de un minuto.</p></div>`;
 h+=`<div class="steps">${[0,1,2].map(i=>`<i class="${i<=S.step?'on':''}"></i>`).join('')}</div>`;
 if(S.step===0)h+=`<div class="sec"><h2>1 · Servicios</h2><small>toca para agregar</small></div><div class="grid">${cfg.services.map(s=>`<div class="svc ${S.sel.has(s.id)?'on':''}" onclick="tg('${s.id}')"><span class="ck">${S.sel.has(s.id)?'✓':''}</span><div class="ic">${s.ic||'🏍️'}</div><h3>${esc(s.name)}</h3><p>${esc(s.d||'')}</p><div class="pr"><span>${COP(s.price)}</span><em>${s.min} min</em></div></div>`).join('')}</div>`;
 if(S.step===0&&(cfg.combos||[]).some(c=>c.ids.every(x=>cfg.services.some(s=>s.id===x))))h+=`<div class="sec"><h2>Combos</h2><small>ahorra al juntar</small></div><div class="cards">${cfg.combos.map((c,i)=>c.ids.every(x=>cfg.services.some(s=>s.id===x))?`<div class="cd" style="cursor:pointer;${c.ids.every(x=>S.sel.has(x))?'border-color:var(--ac)':''}" onclick="cmb(${i})"><div class="ic">🎁</div><h3>${esc(c.n)}</h3><p>${c.ids.map(x=>cfg.services.find(s=>s.id===x).name).join(' + ')}</p><b style="color:var(--ac)">-${c.pct}%</b></div>`:'').join('')}</div>`;
 if(S.step===1)h+=`<div class="sec"><h2>2 · Cuándo y con quién</h2><small>${mins()} min estimados</small></div><div class="chips">${days.map(d=>`<div class="chip ${ymd(d)===S.date?'on':''}" onclick="sd('${ymd(d)}')"><small>${DN[d.getDay()]}</small><b>${d.getDate()}</b></div>`).join('')}</div><div class="staff">${cfg.staff.map(p=>`<div class="person ${S.staff===p.id?'on':''}" onclick="sp('${p.id}')"><div class="av">${esc(p.name[0]||'?')}</div><div><b>${esc(p.name)}</b><small>${[...Array(N).keys()].filter(i=>{const o=S.staff;S.staff=p.id;const r=free(i);S.staff=o;return r}).length} horarios libres</small></div></div>`).join('')}</div><div class="sec"><h2>Horas</h2></div>${S.staff==null?'<p class="empty">Elige primero quién lavará tu moto.</p>':`<div class="slots">${[...Array(N).keys()].map(i=>`<div class="slot ${free(i)?'':'x'} ${S.slot===i?'on':''}" onclick="${free(i)?`ss(${i})`:''}">${lab(i)}</div>`).join('')}</div>`}`;
 if(S.step===2)h+=`<div class="sec"><h2>3 · Tus datos</h2></div><div class="f"><input id="fn" placeholder="Tu nombre" value="${esc(S.f.name)}"><input id="fp" placeholder="Celular de contacto" inputmode="tel" value="${esc(S.f.phone)}"><input id="fpl" placeholder="Placa de la moto (ej. ABC12D)" maxlength="8" style="text-transform:uppercase" value="${esc(S.f.placa||'')}" oninput="S.f.placa=pk(this.value);syncNext()" onchange="this.value=S.f.placa||'';lookClient(S.f.placa)"><input id="fm" placeholder="Moto (marca y modelo)" value="${esc(S.f.moto)}"><input id="fo" class="wide" placeholder="Notas: rayones, zonas a cuidar, algo especial que quieras" value="${esc(S.f.note||'')}" onchange="S.f.note=this.value"><input id="fc" placeholder="Código de aliado (opcional)" value="${esc(S.f.code||'')}" onchange="S.f.code=this.value;checkCode(this.value)"></div><div class="sec"><h2>Forma de pago</h2><small>pagas al recibir tu moto</small></div><div class="staff">${(cfg.pm||[]).map((p,i)=>`<div class="person ${S.f.pmi===p.n?'on':''}" onclick="S.f.pmi=cfg.pm[${i}].n;render()"><b>${esc(p.n)}</b></div>`).join('')}</div>${(()=>{const p=(cfg.pm||[]).find(x=>x.n===S.f.pmi);return p&&p.d?`<div class="note" style="color:var(--tx)">💳 ${esc(p.d)}</div>`:''})()}<div class="ticket" style="max-width:none"><div><span>Cita</span><b>${S.date} · ${lab(S.slot)} con ${esc(sName(S.staff))}</b></div>${cfg.services.filter(s=>S.sel.has(s.id)).map(s=>`<div><span>${esc(s.name)}</span><b>${COP(s.price)}</b></div>`).join('')}${disc()>0?`<div><span>Descuentos</span><b>-${COP(disc())}</b></div>`:''}<div><span>Total a pagar</span><b style="color:var(--ac)">${COP(tot())}</b></div></div>`;
 if(!db)h+=`<div class="note">Modo demostración: las citas no se guardan porque no hay sesión activa.</div>`;
 a.innerHTML=h;
 $('#tv').textContent=COP(tot());$('#tl').textContent=S.sel.size?S.sel.size+' servicio(s)':'Total';
 $('#back').style.display=S.step?'':'none';
 const ok=[S.sel.size>0,S.slot!=null&&S.staff!=null,S.f.name.trim()&&S.f.phone.trim()&&pk(S.f.placa||'').length>=5][S.step];
 $('#next').disabled=!ok;$('#next').textContent=S.step===2?'Confirmar cita ✓':'Siguiente →';
 ['fn','fp','fm'].forEach((id,k)=>{const el=$('#'+id);if(el)el.oninput=()=>{S.f[['name','phone','moto'][k]]=el.value;syncNext()}});}
const TABS=[['reserva','🏍️ Reservar'],['nosotros','Nosotros'],['sede','Sede'],['aliados','Aliados'],['horarios','Horarios'],['faq','Preguntas']];
function tabsHtml(){return waBtn()+`<div class="tabs cl">${TABS.map(t=>`<button class="tab ${t[0]==='reserva'?'rs ':''}${S.page===t[0]?'on':''}" onclick="gp('${t[0]}')">${t[1]}</button>`).join('')}</div>`}
window.gp=p=>{S.page=p;render();scrollTo({top:0,behavior:'smooth'})};
const HR=[['Lunes','8:00 a. m. – 6:00 p. m.'],['Martes','8:00 a. m. – 6:00 p. m.'],['Miércoles','8:00 a. m. – 6:00 p. m.'],['Jueves','8:00 a. m. – 6:00 p. m.'],['Viernes','8:00 a. m. – 6:00 p. m.'],['Sábado','8:00 a. m. – 6:00 p. m.'],['Domingo','8:00 a. m. – 6:00 p. m.']];
const CTA=`<div class="cta"><div><h3>¿Lista tu moto para brillar?</h3><span>Reserva en menos de un minuto.</span></div><button class="btn" onclick="gp('reserva')">Reservar ahora →</button></div>`;
const FAQ=[['¿Cuánto dura un lavado?','Depende de los servicios que elijas: desde 30 minutos para un lavado general hasta más de una hora si combinas varios. Al reservar ves el tiempo estimado y solo te mostramos horas donde cabe todo.'],['¿Puedo elegir quién lava mi moto?','Sí. En el paso 2 escoges la persona de lavado y ves sus horarios libres en tiempo real.'],['¿Cómo veo el precio final?','Al marcar los servicios, el total se actualiza al instante y lo ves de nuevo en el resumen antes de confirmar.'],['¿Cómo pago?','El pago se hace en la sede al recibir tu moto. Confirma con nosotros los medios disponibles.'],['¿Puedo cancelar o cambiar mi cita?','Sí, avísanos con anticipación para liberar el espacio y reagendarte sin problema.'],['¿Qué diferencia hay entre lavado general, pro y avanzado?','El general es lavado y secado completo. El pro suma cadena, rines y plásticos detallados. El avanzado agrega motor y acabado de exhibición.'],['¿Hacen lavado de casco?','Sí, exterior, interior y desinfección. Puedes agregarlo a cualquier otro servicio.'],['¿Qué beneficios tienen los aliados?','Conductores de apps de transporte y domicilios, y talleres aliados, tienen tarifas y atención preferencial. Mira la pestaña Aliados.'],['¿Qué pasa si llego tarde?','Te esperamos unos minutos; si el retraso es largo, reprogramamos según la disponibilidad del día.']];
function pages(){const p=S.page,n=new Date(),m=n.getHours()*60+n.getMinutes(),open=m>=480&&m<1080;let h='<div class="pg">';
 if(p==='nosotros')h+=`<h1>Hecho por <span>motociclistas</span>,<br>para motociclistas.</h1><p>Spa Motos 20IVI nació de una idea simple: tu moto es tu herramienta, tu transporte y tu orgullo, y merece un cuidado de verdad, no un lavado a las carreras.</p><div class="nums"><div><b>9</b><small>servicios</small></div><div><b>${cfg.staff.length}</b><small>personas de lavado</small></div><div><b>7</b><small>días a la semana</small></div></div><div class="cards"><div class="cd"><div class="ic">🎯</div><h3>Detalle</h3><p>Cada rincón: rines, cadena, plásticos y carenajes.</p></div><div class="cd"><div class="ic">⏱️</div><h3>Puntualidad</h3><p>Reservas con hora y persona asignada. Sin filas ni esperas.</p></div><div class="cd"><div class="ic">💚</div><h3>Precio claro</h3><p>Ves el total antes de confirmar. Sin sorpresas.</p></div><div class="cd"><div class="ic">🛡️</div><h3>Cuidado</h3><p>Productos pensados para proteger la pintura y las piezas de tu moto.</p></div></div><div class="sec"><h2>Antes y después</h2><small>desliza</small></div>${BA}`;
 if(p==='sede')h+=`<h1>Nuestra <span>sede</span></h1><p>Llega, entrega tu moto y relájate mientras la dejamos como nueva.</p><div class="map"><div class="pin">📍</div></div><div class="cards"><div class="cd"><div class="ic">🏠</div><h3>Dirección</h3><p>${esc(cfg.set.addr||'Por confirmar')}</p>${cfg.set.addr?`<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px"><a class="btn" style="text-decoration:none" target="_blank" href="https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(cfg.set.addr)}&travelmode=driving">🧭 Cómo llegar desde mi ubicación</a><a class="btn g" style="text-decoration:none" target="_blank" href="https://waze.com/ul?q=${encodeURIComponent(cfg.set.addr)}&navigate=yes">Abrir en Waze</a></div>`:''}</div><div class="cd"><div class="ic">🅿️</div><h3>Parqueo</h3><p>Espacio para dejar tu moto mientras esperas.</p></div><div class="cd"><div class="ic">☕</div><h3>Sala de espera</h3><p>Puedes quedarte mientras trabajamos en tu moto.</p></div></div>`;
 if(p==='aliados')h+=`<h1>Aliados <span>20IVI</span></h1><p>Si vives sobre dos ruedas, tu moto trabaja todos los días. Por eso tenemos alianzas con conductores y talleres.</p><div class="cards"><div class="cd"><div class="ic">🚖</div><h3>DiDi</h3><p>Tarifa preferencial para conductores y mensajeros.</p></div><div class="cd"><div class="ic">🧭</div><h3>inDrive</h3><p>Atención rápida para que pierdas poco tiempo sin trabajar.</p></div><div class="cd"><div class="ic">🚗</div><h3>Uber</h3><p>Beneficios para conductores que usan su moto a diario.</p></div><div class="cd"><div class="ic">📦</div><h3>Domicilios</h3><p>Rappi y otras apps de entregas: tu moto limpia, tu imagen impecable.</p></div><div class="cd"><div class="ic">🔧</div><h3>Talleres</h3><p>Alianza con talleres: nos recomiendan y los recomendamos.</p></div><div class="cd"><div class="ic">🎟️</div><h3>${cfg.set.ally}% de descuento</h3><p>Usa tu código de aliado${cfg.set.code?': <b style="color:var(--ac)">'+esc(cfg.set.code)+'</b>':''} al reservar y el precio se ajusta solo.</p></div><div class="cd"><div class="ic">🏆</div><h3>Club 20IVI</h3><p>Acumula lavados y pide tu recompensa en sede. Condiciones por definir.</p></div><div class="cd"><div class="ic">🤝</div><h3>¿Tu empresa?</h3><p>Escríbenos y armamos un plan para tu equipo o tu taller.</p></div></div>`;
 if(p==='horarios')h+=`<h1>Nuestros <span>horarios</span></h1><span class="st ${open?'o':''}"><i></i>${open?'Abierto ahora':'Cerrado ahora'}</span><div class="hrs">${HR.map((r,i)=>`<div class="${(i+1)%7===n.getDay()?'hoy':''}"><span>${r[0]}</span><span>${r[1]}</span></div>`).join('')}</div><p>Las citas se agendan en bloques de 30 minutos, según la disponibilidad de cada persona.</p>`;
 if(p==='faq')h+=`<h1>Preguntas <span>frecuentes</span></h1><div style="margin-top:18px">${FAQ.map(q=>`<details><summary>${q[0]}</summary><p>${q[1]}</p></details>`).join('')}</div>`;
 return h+CTA+'</div>'}
const NX={pend:'proc',proc:'ok',ok:'pend'},LB={pend:'⏳ Pendiente',proc:'🧽 En proceso',ok:'✅ Terminada'};
window.stNext=(id,st)=>db&&db.collection('bookings').doc(id).update({st});
window.cmb=i=>{const c=cfg.combos[i],all=c.ids.every(x=>S.sel.has(x));c.ids.forEach(x=>all?S.sel.delete(x):S.sel.add(x));S.slot=null;render()};
function waBtn(){const w=cfg.set&&cfg.set.wa;return w&&!isAdminView()?`<a class="wab" target="_blank" href="https://wa.me/${w}">💬</a>`:''}
const BA=`<div class="ba"><div class="bf">ANTES</div><div class="af">DESPUÉS</div><input type="range" min="0" max="100" value="50" oninput="this.parentNode.style.setProperty('--p',this.value+'%')"></div><p class="empty">Ejemplo visual: aquí van tus fotos reales de antes y después.</p><div class="sec"><h2>Reseñas</h2></div><div class="cards">${['Dejó mi moto como nueva.','Rápidos y con precio claro.','Mi cadena quedó impecable.'].map((t,i)=>`<div class="cd"><div>⭐⭐⭐⭐⭐</div><p>“${t}”</p><small style="color:var(--mut)">Cliente ${i+1} · ejemplo</small></div>`).join('')}</div>`;
function bloqHtml(){S.bs=S.bs||(cfg.staff[0]||{}).id;return `<div class="chips">${days.map(d=>`<div class="chip ${ymd(d)===S.date?'on':''}" onclick="S.adate=S.date='${ymd(d)}';watchSlots();watchBooks()"><small>${DN[d.getDay()]}</small><b>${d.getDate()}</b></div>`).join('')}</div><div class="staff">${cfg.staff.map(p=>`<div class="person ${S.bs===p.id?'on':''}" onclick="S.bs='${p.id}';render()"><div class="av">${esc(p.name[0]||'?')}</div><b>${esc(p.name)}</b></div>`).join('')}</div><div class="sec"><h2>Toca una hora para bloquearla</h2></div><div class="slots">${[...Array(N).keys()].map(i=>{const k=S.bs+'_'+i;return `<div class="slot ${S.blk&&S.blk.has(k)?'on':S.taken.has(k)?'x':''}" onclick="tgBlk(${i})">${lab(i)}</div>`}).join('')}</div><div style="display:flex;gap:8px;margin-top:14px"><button class="btn g" onclick="blkDay(1)">Bloquear día</button><button class="btn g" onclick="blkDay(0)">Liberar día</button></div><p class="empty">Naranja = bloqueada por ti. Tachada = ya tiene cita.</p>`}
