function clRows(){const q=(S.q||'').toLowerCase(),f=S.cf||'all',lim=ymd(new Date(Date.now()-30*864e5)),L=clients().filter(c=>(!q||(c.name+c.phone+(c.placa||'')+[...c.motos].join()).toLowerCase().includes(q))&&(f==='all'||(f==='vip'&&c.vip)||(f==='rec'&&c.n>=3)||(f==='ina'&&c.last<lim)||(f==='dsc'&&c.disc>0)));return L.length?L.map(c=>`<div class="cd" style="margin-bottom:10px"><div class="jh"><h3>${esc(c.name)}${c.vip?' ⭐':''}</h3>${c.disc?`<span style="color:var(--ac2);font-weight:700">🎁 ${c.disc}%</span>`:''}</div><p>🔖 ${esc(c.placa||'sin placa')} · 📞 ${esc(c.phone)} · 🏍️ ${esc([...c.motos].join(', ')||'—')}</p><div class="nums" style="margin:10px 0"><div><b>${c.n}</b><small>visitas</small></div><div><b>${COP(c.total)}</b><small>gastado</small></div><div><b style="font-size:26px">${c.last||'—'}</b><small>última cita</small></div></div><p>Favorito: ${esc(c.fav||'—')}</p>${c.note?`<p>📝 ${esc(c.note)}</p>`:''}<div class="acts"><span onclick="cDisc('${c.k}')">🎁 Descuento</span><span onclick="cVip('${c.k}')">⭐ ${c.vip?'Quitar VIP':'VIP'}</span><span onclick="cNote('${c.k}')">📝 Nota</span><span onclick="cWa('${c.k}')">💬 WhatsApp</span></div><details style="margin-top:10px"><summary>Historial (${c.n})</summary>${[...c.hist].sort((x,y)=>x.date<y.date?1:-1).map(b=>`<div class="ap" style="margin:6px 0"><b>${b.date}</b> ${lab(b.start)} · ${b.svc.map(esc).join(', ')}<small>${COP(b.total)}${b.note?' · 📝 '+esc(b.note):''}</small></div>`).join('')}</details></div>`).join(''):'<p class="empty">Aún no hay clientes con ese filtro.</p>'}
function clientsHtml(){return `<div class="f"><input placeholder="Buscar por nombre, celular o moto" value="${esc(S.q||'')}" oninput="S.q=this.value;clRefresh()"></div><div class="chips" style="margin-top:10px">${[['all','Todos'],['vip','⭐ VIP'],['rec','🔁 3+ visitas'],['ina','😴 Inactivos 30+ días'],['dsc','🎁 Con descuento']].map(f=>`<div class="chip ${(S.cf||'all')===f[0]?'on':''}" style="min-width:auto" onclick="S.cf='${f[0]}';render()"><b style="font-size:16px">${f[1]}</b></div>`).join('')}</div><div class="f" style="margin:8px 0"><label style="color:var(--mut);font-size:13px">Mensaje de promoción (usa {nombre} y {desc})<input value="${esc(S.msg||MSG)}" onchange="S.msg=this.value"></label></div><div id="cl">${clRows()}</div>`}
window.clRefresh=()=>{const e=document.getElementById('cl');if(e)e.innerHTML=clRows()};
const cs=(k,p)=>{const o={...(S.cdm||{})[k],...(S.cnm||{})[k]},n={disc:+o.disc||0,vip:!!o.vip,note:o.note||'',...p};return Promise.all([db.collection('clients').doc(k).set({disc:n.disc}),db.collection('cnotes').doc(k).set({vip:n.vip,note:n.note})])};
window.cDisc=k=>{const c=clients().find(x=>x.k===k),v=prompt('Descuento en % para '+c.name+' (0 para quitarlo)',c.disc);if(v!==null)cs(k,{disc:Math.max(0,Math.min(100,+v||0))})};
