window.cWa=k=>{const c=clients().find(x=>x.k===k),t=(S.msg||MSG).replace('{nombre}',c.name.split(' ')[0]).replace('{desc}',c.disc||0);window.open('https://wa.me/'+wd(c.phone)+'?text='+encodeURIComponent(t),'_blank')};
window.detB=id=>{const b=(S.all||[]).find(x=>x.id===id);if(!b)return;const sv=cfg.services.filter(s=>b.svc.includes(s.name)),sum=sv.reduce((a,s)=>a+s.price,0),k=ck(b),h=(S.all||[]).filter(x=>ck(x)===k),st=sg(b),m=document.createElement('div');m.id='md';m.className='md';m.innerHTML=`<div class="mb"><h3 style="font-size:30px">Detalle de la cita</h3><div class="ticket" style="max-width:none"><div><span>Cliente</span><b>${esc(b.name)}</b></div><div><span>Celular</span><b>${esc(b.phone||'—')}</b></div><div><span>Moto</span><b>${esc(b.moto||'—')}</b></div><div><span>Placa</span><b>${esc(b.placa||'—')}</b></div><div><span>Cuándo</span><b>${b.date} · ${lab(b.start)}–${lab(b.start+b.n)}</b></div><div><span>Atiende</span><b>${esc(sName(b.staff))}</b></div><div><span>Pago</span><b>${b.pay==='ok'?'✅ '+esc(b.pm||'Pagado'):b.pmi?'💳 Pagará con '+esc(b.pmi):'💰 Pendiente'}</b></div><div><span>Estado</span><b>${st<0?'⏳ Pendiente':st>=7?'🏁 Lista':STG[st][1]+' '+STG[st][0]}</b></div></div><div class="sec"><h2>Lo que pidió</h2></div><div class="ticket" style="max-width:none">${sv.map(s=>`<div><span>${esc(s.name)}</span><b>${COP(s.price)}</b></div>`).join('')}${sum>b.total?`<div><span>Descuentos${b.code?' · código '+esc(b.code):''}${b.cd?' · cliente '+b.cd+'%':''}</span><b>-${COP(sum-b.total)}</b></div>`:''}<div><span>Total</span><b style="color:var(--ac)">${COP(b.total)}</b></div></div>${b.note?`<div class="note" style="color:var(--tx)">📝 <b>Nota del cliente:</b> ${esc(b.note)}</div>`:'<p class="empty">El cliente no dejó notas.</p>'}<div class="sec"><h2>Historial</h2><small>${h.length} cita(s) con este número</small></div>${[...h].sort((x,y)=>x.date<y.date?1:-1).map(x=>`<div class="ap" style="margin-bottom:6px"><b>${x.date}</b> · ${x.svc.map(esc).join(', ')}<small>${COP(x.total)}</small></div>`).join('')}<div style="margin-top:14px"><button class="btn g" onclick="document.getElementById('md').remove()">Cerrar</button></div></div>`;document.body.appendChild(m)};
const _w2=setInterval(()=>{if(db){clearInterval(_w2);if(isAdmin){db.collection('clients').onSnapshot(q=>{S.cdm={};q.docs.forEach(d=>S.cdm[d.id]=d.data());if(isAdminView()&&S.tab==='cli')render()},()=>{});db.collection('cnotes').onSnapshot(q=>{S.cnm={};q.docs.forEach(d=>S.cnm[d.id]=d.data());if(isAdminView()&&S.tab==='cli')render()},()=>{})}}},500);
const nowIdx=d=>{if(d!==ymd(new Date()))return 0;const n=new Date();return Math.max(0,Math.ceil((n.getHours()*60+n.getMinutes()-480)/30))};
async function busy(date,ex){const sn=await db.collection('slots').where('date','==',date).get();return new Set(sn.docs.filter(d=>d.data().bid!==ex).map(d=>d.data().staff+'_'+d.data().i))}
async function findWin(date,n,from,ex,pref,only){const bz=await busy(date,ex),st=only?cfg.staff.filter(p=>p.id===only):[...cfg.staff].sort((a,b)=>(b.id===pref)-(a.id===pref));for(let i=from;i+n<=N;i++)for(const p of st){let ok=true;for(let k=0;k<n;k++)if(bz.has(p.id+'_'+(i+k))){ok=false;break}if(ok)return{staff:p.id,i}}return null}
async function place(b,staff,i,x){await Promise.all([...Array(b.n)].map((_,k)=>db.collection('slots').doc(b.id+'_'+k).delete()));await Promise.all([...Array(b.n)].map((_,k)=>db.collection('slots').doc(b.id+'_'+k).set({date:b.date,staff,i:i+k,bid:b.id})));await db.collection('bookings').doc(b.id).update({staff,start:i,wait:false,...(x||{})})}
window.avisar=id=>{const b=(S.all||[]).find(x=>x.id===id);if(!b)return;const f=b.name.split(' ')[0],t=b.moved?`Hola ${f}, adelantamos tu turno en Spa Motos 20IVI a las ${lab(b.start)}. ¿Puedes llegar? 🏍️`:b.late?`Hola ${f}, tu cita en Spa Motos 20IVI se reagendó para las ${lab(b.start)} con ${sName(b.staff)} (día ${b.date}). Recuerda: tienes 10 minutos de tolerancia.`:`Hola ${f}, tu turno en Spa Motos 20IVI empieza en unos 10 a 15 minutos 🏍️`;window.open('https://wa.me/'+wd(b.phone)+'?text='+encodeURIComponent(t),'_blank')};
async function promote(staff,i,lb){const cand=(S.all||[]).filter(x=>x.date===lb.date&&x.wait&&x.id!==lb.id&&x.n<=lb.n).sort((a,c)=>a.created-c.created)[0];if(cand){await place(cand,staff,i,{});return cand.name+' (lista de espera) pasa a las '+lab(i)+' con '+sName(staff)}const nx=(S.all||[]).filter(x=>x.date===lb.date&&x.staff===staff&&!x.wait&&x.id!==lb.id&&x.start>i&&sg(x)<0).sort((a,c)=>a.start-c.start)[0];if(nx&&i>=nowIdx(lb.date)){const bz=await busy(lb.date,nx.id);let ok=true;for(let k=0;k<nx.n;k++)if(bz.has(staff+'_'+(i+k)))ok=false;if(ok&&confirm('¿Adelantar a '+nx.name+' (de '+lab(nx.start)+' a '+lab(i)+') en el turno libre de '+sName(staff)+'?')){await place(nx,staff,i,{moved:true});return nx.name+' se adelanta a las '+lab(i)+' con '+sName(staff)}}return''}
window.lateB=async id=>{const b=(S.all||[]).find(x=>x.id===id);if(!b||!db)return;if(!confirm(b.name+' llegó tarde (más de 10 min). Se libera su turno, pasa el siguiente en la cola y se reagenda en el próximo espacio libre del día. ¿Continuar?'))return;const oS=b.staff,oI=b.start,lf=lab(oI)+' · '+sName(oS);await Promise.all([...Array(b.n)].map((_,k)=>db.collection('slots').doc(id+'_'+k).delete()));const a=await promote(oS,oI,b),w=await findWin(b.date,b.n,Math.max(nowIdx(b.date),oI+1),id,oS);if(w)await place(b,w.staff,w.i,{late:true,lateFrom:lf});else await db.collection('bookings').doc(id).update({wait:true,late:true,lateFrom:lf,staff:null});toast((a?a+'. ':'')+(w?b.name+' reagendado a las '+lab(w.i)+' con '+sName(w.staff):b.name+' queda en lista de espera'))};
async function autoNext(b){if(!b.staff)return;const w=(S.all||[]).filter(x=>x.date===b.date&&x.wait&&x.id!==b.id).sort((a,c)=>a.created-c.created)[0];if(!w)return;const from=Math.max(0,Math.ceil((new Date().getHours()*60+new Date().getMinutes()+15-480)/30)),r=await findWin(b.date,w.n,from,w.id,b.staff,b.staff);if(r){await place(w,r.staff,r.i,{});toast('✅ '+w.name+' pasa a las '+lab(r.i)+' con '+sName(r.staff))}}
window.setStg=async(id,i)=>{if(!db)return;const u={stg:i,st:i>=7?'ok':'proc'};u['t'+i]=Date.now();if(i>=7)u.tEnd=Date.now();await db.collection('bookings').doc(id).update(u);if(i>=7){const b=(S.all||[]).find(x=>x.id===id);if(b)autoNext(b)}};
window.assignW=async id=>{const b=(S.all||[]).find(x=>x.id===id);if(!b)return;const w=await findWin(b.date,b.n,nowIdx(b.date),id,null);if(!w)return alert('No hay espacio libre ese día para ese tiempo. Usa Editar para moverla a otro día.');await place(b,w.staff,w.i,{});toast('✅ '+b.name+' · '+lab(w.i)+' con '+sName(w.staff))};
window.payB=id=>{const b=(S.all||[]).find(x=>x.id===id);if(!b)return;const m=document.createElement('div');m.id='md';m.className='md';m.innerHTML=`<div class="mb"><h3 style="font-size:30px">Cobrar ${COP(b.total)}</h3><p class="empty">${esc(b.name)}${b.pmi?' · pensaba pagar con '+esc(b.pmi):''}</p><div class="cards" style="grid-template-columns:1fr 1fr">${(cfg.pm||[]).map((p,i)=>`<button class="btn" onclick="setPay('${id}',${i})">${esc(p.n)}</button>`).join('')}</div>${b.pay==='ok'?`<button class="btn r" onclick="setPay('${id}','')">Marcar como pendiente</button> `:''}<button class="btn g" onclick="document.getElementById('md').remove()">Cerrar</button></div>`;document.body.appendChild(m)};
