const _jc=jobCard;jobCard=function(b){const c=sg(b),nw=new Date(),over=b.date===ymd(nw)&&c<0&&!b.wait&&nw.getHours()*60+nw.getMinutes()>480+b.start*30+10,bd=(b.placa?`<span class="badge ok">🔖 ${esc(b.placa)}</span> `:'')+(b.pay==='ok'?`<span class="badge ok">✅ ${esc(b.pm||'Pagado')}</span> `:'')+(over?'<span class="badge">⚠️ +10 min de retraso</span> ':'')+(b.late?`<span class="badge">⏰ Reagendado (antes ${esc(b.lateFrom||'')})</span> `:'')+(b.moved?'<span class="badge ok">⬆ Adelantado</span> ':'')+(b.walk?'<span class="badge">🚶 Walk-in</span> ':''),bt=(c<0?`<span ${over?'style="background:var(--ac2);color:#1b1a12;font-weight:700"':''} onclick="lateB('${b.id}')">⏰ Llegó tarde</span>`:'')+(b.pay==='ok'?'':`<span onclick="payB('${b.id}')">💰 Cobrar</span>`)+((b.late||b.moved)&&b.phone?`<span onclick="avisar('${b.id}')">💬 Avisar</span>`:'');return _jc(b).replace('<div class="acts">',(bd?'<div style="margin:6px 0">'+bd+'</div>':'')+'<div class="acts">'+bt)};
function waitHtml(){const w=(S.books||[]).filter(b=>b.wait);return `<div class="acts" style="margin:0 0 12px"><span onclick="walkin()" style="background:var(--ac);color:#1b1a12;font-weight:700">+ Nueva cita</span>${isAdmin&&location.hash!=='#taller'?'<span onclick="clearDay()">🗑 Eliminar todas del día</span>':''}</div>`+(w.length?`<div class="col" style="margin-bottom:12px;min-height:0"><h3>⏳ Lista de espera <small style="color:var(--mut);font-size:16px">${w.length}</small></h3>${w.map(b=>`<div class="job"><div class="jh"><b>${esc(b.name)}</b><span>🏍️ ${esc(b.moto||'—')}</span></div><small class="sv">${b.svc.map(esc).join(', ')}</small>${b.late?'<div style="margin:6px 0"><span class="badge">⏰ Llegó tarde · sin espacio hoy</span></div>':''}<div class="acts"><span onclick="assignW('${b.id}')">✅ Asignar ahora</span><span onclick="editB('${b.id}')">✏️ Editar</span><span onclick="delB('${b.id}')">🗑</span></div></div>`).join('')}</div>`:'')}
function bufHtml(){const bs=S.books||[],now=Date.now();return cfg.staff.map(p=>{const js=bs.filter(b=>b.staff===p.id&&!b.wait),fin=js.filter(b=>b.st==='ok'&&b.tEnd&&now-b.tEnd<9e5).sort((a,c)=>c.tEnd-a.tEnd)[0];if(!fin)return'';const nx=js.filter(b=>b.start>fin.start&&sg(b)<0).sort((a,c)=>a.start-c.start)[0],left=Math.max(0,Math.ceil((9e5-(now-fin.tEnd))/6e4));return `<div class="note" style="color:var(--tx)">⏳ <b>${esc(p.name)}</b> terminó ${esc(fin.moto||'una moto')}. ${nx?`Pausa de ${left} min antes de atender a <b>${esc(nx.name)}</b> (${lab(nx.start)}). <span class="pill" style="cursor:pointer" onclick="avisar('${nx.id}')">Avisar al siguiente</span>`:'No hay más citas en cola ✅'}</div>`}).join('')}
const _th=tallerHtml;tallerHtml=function(){return waitHtml()+bufHtml()+_th()};
window.walkin=()=>{const m=document.createElement('div');m.id='md';m.className='md';m.innerHTML=`<div class="mb"><h3 style="font-size:30px">Walk-in 🚶</h3><div class="f" style="margin-top:10px"><input id="w1" placeholder="Nombre"><input id="w2" placeholder="Celular (opcional)" inputmode="tel"><input id="w3" placeholder="Moto"><input id="w6" placeholder="Placa" style="text-transform:uppercase"><select id="w4"><option value="">Primera persona disponible</option>${cfg.staff.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></div><div class="sec"><h2>Servicios</h2></div><div id="w5">${cfg.services.map(s=>`<label class="cb"><input type="checkbox" value="${s.id}"> ${esc(s.name)} · ${COP(s.price)}</label>`).join('')}</div><div style="display:flex;gap:8px;margin-top:14px"><button class="btn" onclick="saveW()">Registrar</button><button class="btn g" onclick="document.getElementById('md').remove()">Cerrar</button></div></div>`;document.body.appendChild(m)};
window.saveW=async()=>{const g=x=>document.getElementById(x).value,ids=[...document.querySelectorAll('#w5 input:checked')].map(x=>x.value),ss=cfg.services.filter(s=>ids.includes(s.id));if(!g('w1').trim()||!ss.length)return alert('Pon el nombre y al menos un servicio.');const date=ymd(new Date()),n=Math.max(1,Math.ceil(ss.reduce((a,s)=>a+s.min,0)/30)),id='b'+Date.now().toString(36),pf=g('w4')||null,w=await findWin(date,n,nowIdx(date),id,pf,pf),b={id,date,staff:w?w.staff:null,start:w?w.i:0,n,svc:ss.map(s=>s.name),total:ss.reduce((a,s)=>a+s.price,0),name:g('w1').trim(),phone:g('w2'),moto:g('w3'),placa:pk(g('w6')),walk:true,wait:!w,st:'pend',created:Date.now()};await db.collection('bookings').doc(id).set(b);if(w)await Promise.all([...Array(n)].map((_,k)=>db.collection('slots').doc(id+'_'+k).set({date,staff:w.staff,i:w.i+k,bid:id})));document.getElementById('md').remove();toast(w?'✅ '+b.name+' · '+lab(w.i)+' con '+sName(w.staff):'⏳ Sin espacio hoy: queda en lista de espera')};
function cajaHtml(){const d=S.cd||ymd(new Date()),bs=(S.all||[]).filter(x=>x.date===d&&!x.wait),paid=bs.filter(x=>x.pay==='ok'),pend=bs.filter(x=>x.pay!=='ok'),M=(cfg.pm||[]).map(p=>p.n),sum=a=>a.reduce((s,x)=>s+x.total,0),by=m=>sum(paid.filter(x=>x.pm===m)),cl=(S.cim||{})[d],ef=by('Efectivo');return `<div class="f" style="max-width:260px;margin-bottom:12px"><input type="date" value="${d}" onchange="S.cd=this.value;render()"></div><div class="stats"><div class="stat"><b>${COP(sum(bs))}</b><small>esperado del día</small></div><div class="stat"><b>${COP(sum(paid))}</b><small>cobrado</small></div><div class="stat"><b>${COP(sum(pend))}</b><small>pendiente (${pend.length})</small></div></div><div class="cd" style="margin-bottom:12px">${M.map(m=>`<div class="br"><span>${m}</span><div class="bw"><i style="width:${sum(paid)?by(m)/sum(paid)*100:0}%"></i></div><em>${COP(by(m))}</em></div>`).join('')}</div><div class="cd"><h3>Cierre de caja</h3><p>Efectivo esperado: <b style="color:var(--ac)">${COP(ef)}</b></p><div class="f" style="max-width:320px"><input id="cj" type="number" placeholder="Efectivo contado" value="${cl?cl.contado:''}"></div><div style="display:flex;gap:8px;margin-top:10px;align-items:center;flex-wrap:wrap"><button class="btn" onclick="cierre('${d}',${ef})">${cl?'Actualizar cierre':'Cerrar caja'}</button>${cl?`<span class="badge ${cl.contado===cl.esp?'ok':''}">Cierre guardado · diferencia ${COP(cl.contado-cl.esp)}</span>`:''}</div></div>${pend.length?`<div class="sec"><h2>Pendientes de cobro</h2></div>${pend.map(x=>`<div class="ap"><b>${lab(x.start)} · ${esc(x.name)}</b><small>${x.svc.map(esc).join(', ')}</small><div style="display:flex;justify-content:space-between;align-items:center;margin-top:6px"><b style="color:var(--ac)">${COP(x.total)}</b><button class="btn g" style="padding:8px 12px;font-size:13px" onclick="payB('${x.id}')">💰 Cobrar</button></div></div>`).join('')}`:''}`}
