window.walkin=()=>{const m=document.createElement('div');m.id='md';m.className='md';m.innerHTML=`<div class="mb"><h3 style="font-size:30px">Nueva cita</h3><p class="empty">Esc para cerrar</p><div class="f" style="margin-top:6px"><input id="w1" placeholder="Nombre"><input id="w2" placeholder="Celular de contacto" inputmode="tel"><input id="w6" placeholder="Placa" maxlength="8" style="text-transform:uppercase"><input id="w3" placeholder="Moto"><select id="w7">${days.map(d=>`<option value="${ymd(d)}">${DN[d.getDay()]} ${ymd(d)}</option>`).join('')}</select><select id="w8"><option value="">Lo antes posible (llega ahora)</option>${[...Array(N).keys()].map(i=>`<option value="${i}">${lab(i)}</option>`).join('')}</select><select id="w4"><option value="">Primera persona disponible</option>${cfg.staff.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></div><div class="sec"><h2>Servicios</h2></div><div id="w5">${cfg.services.map(s=>`<label class="cb"><input type="checkbox" value="${s.id}"> ${esc(s.name)} · ${COP(s.price)}</label>`).join('')}</div><div style="display:flex;gap:8px;margin-top:14px"><button class="btn" onclick="saveW()">Registrar</button><button class="btn g" onclick="document.getElementById('md').remove()">Cerrar</button></div></div>`;document.body.appendChild(m);document.getElementById('w1').focus()};
