function loginHtml(kind){const adm=kind==='admin',first=adm&&!cfg.set.ah;if(adm&&!isAdmin)return '<div class="cd" style="max-width:420px;margin:40px auto;text-align:center"><div class="ic">🔒</div><h3>Acceso restringido</h3><p>Esta sección es solo para el propietario.</p></div>';return `<div class="cd" style="max-width:420px;margin:30px auto"><div class="ic">🔐</div><h3>${first?'Crea tu acceso de administrador':adm?'Acceso de administrador':'Acceso de empleados'}</h3><p>${first?'Elige un usuario y una contraseña (mínimo 4 caracteres).':'Ingresa con tu usuario y contraseña.'}</p><div class="f" style="margin-top:12px;grid-template-columns:1fr"><input id="lu" placeholder="Usuario" autocapitalize="off" autocomplete="username"><input id="lp" type="password" placeholder="Contraseña" autocomplete="current-password" onkeydown="if(event.key==='Enter')doLogin('${kind}')"></div><button class="btn" style="margin-top:12px;width:100%" onclick="doLogin('${kind}')">${first?'Crear y entrar':'Entrar'}</button>${adm&&!first?'<p class="empty" style="margin-top:10px;cursor:pointer;text-decoration:underline" onclick="resetAdm()">Olvidé mi contraseña (soy el propietario)</p>':''}</div>`}
let LK={n:0,t:0};
window.doLogin=async kind=>{const u=document.getElementById('lu').value.trim().toLowerCase(),p=document.getElementById('lp').value;if(Date.now()<LK.t)return alert('Demasiados intentos. Espera un minuto.');if(!u||p.length<4)return alert('Escribe usuario y contraseña (mínimo 4 caracteres).');const ok=(r,id)=>{S.auth={role:r,id};try{sessionStorage.setItem('sm_auth',JSON.stringify(S.auth))}catch(e){}LK.n=0;render()};if(kind==='admin'&&!cfg.set.ah){if(!isAdmin)return;const s=rs();cfg.set.au=u;cfg.set.as=s;cfg.set.ah=await hp(p,s);saveCfg();return ok('admin')}const adm=async()=>isAdmin&&cfg.set.ah&&u===cfg.set.au&&await hp(p,cfg.set.as)===cfg.set.ah;if(kind==='admin'){if(await adm())return ok('admin')}else{const st=cfg.staff.find(x=>x.u===u&&x.h);if(st&&await hp(p,st.s)===st.h)return ok('staff',st.id);if(await adm())return ok('admin')}LK.n++;if(LK.n>=5){LK.t=Date.now()+60000;LK.n=0}await new Promise(r=>setTimeout(r,900));alert('Usuario o contraseña incorrectos.')};
