window.setCred=async k=>{const a=k==='a',u=document.getElementById(a?'au':'su'+k).value.trim().toLowerCase(),p=document.getElementById(a?'ap':'sp'+k).value,t=a?cfg.set:cfg.staff[k],has=a?t.ah:t.h;if(!u)return alert('Escribe un usuario.');const dup=a?cfg.staff.some(x=>x.u===u):(cfg.staff.some((x,j)=>j!==k&&x.u===u)||u===cfg.set.au);if(dup)return alert('Ese usuario ya existe.');if((p&&p.length<4)||(!p&&!has))return alert('La contraseña debe tener al menos 4 caracteres.');if(a)t.au=u;else t.u=u;if(p){const s=rs();if(a){t.as=s;t.ah=await hp(p,s)}else{t.s=s;t.h=await hp(p,s)}}saveCfg();toast('Acceso guardado');render()};
const _aj2=ajHtml;ajHtml=function(){return _aj2()+credHtml()};
function bufHtml(only){const bs=S.books||[],now=Date.now();return cfg.staff.filter(p=>!only||p.id===only).map(p=>{const js=bs.filter(b=>b.staff===p.id&&!b.wait),fin=js.filter(b=>b.st==='ok'&&b.tEnd&&now-b.tEnd<9e5).sort((a,c)=>c.tEnd-a.tEnd)[0];if(!fin)return'';const nx=js.filter(b=>b.start>fin.start&&sg(b)<0).sort((a,c)=>a.start-c.start)[0],left=Math.max(0,Math.ceil((9e5-(now-fin.tEnd))/6e4));return `<div class="note" style="color:var(--tx)">⏳ <b>${esc(p.name)}</b> terminó ${esc(fin.moto||'una moto')}. ${nx?`Pausa de ${left} min antes de atender a <b>${esc(nx.name)}</b> (${lab(nx.start)}). <span class="pill" style="cursor:pointer" onclick="avisar('${nx.id}')">Avisar al siguiente</span>`:'No hay más citas en cola ✅'}</div>`}).join('')}
function staffCard(b){const c=sg(b),nw=new Date(),over=b.date===ymd(nw)&&c<0&&nw.getHours()*60+nw.getMinutes()>480+b.start*30+10;return `<div class="job ${c>=7?'fin':''}"><div class="jh"><b>${lab(b.start)} · ${esc(b.name.split(' ')[0])}</b><span>🔖 ${esc(b.placa||'—')} · 🏍️ ${esc(b.moto||'—')}</span></div><small class="sv">${b.svc.map(esc).join(', ')} · ~${b.n*30} min</small>${b.note?`<div class="note" style="color:var(--tx);margin:8px 0">📝 ${esc(b.note)}</div>`:''}<div style="margin:6px 0">${over?'<span class="badge">⚠️ +10 min de retraso</span> ':''}${b.late?'<span class="badge">⏰ Reagendado</span> ':''}${b.moved?'<span class="badge ok">⬆ Adelantado</span> ':''}</div>${stepper(b,true)}${c>=7?'<div class="okb">🏁 Moto lista</div>':`<button class="btn" onclick="setStg('${b.id}',${c+1})">${c<0?'Iniciar lavado':'Siguiente: '+STG[c+1][0]} →</button>${b.t0?`<div class="el" style="margin-top:8px">⏱ ${Math.round((Date.now()-b.t0)/60000)} min en el taller</div>`:''}`}${c<0?`<div class="acts"><span onclick="lateB('${b.id}')">⏰ Llegó tarde</span></div>`:''}</div>`}
