window.sendRcp=id=>{const k=id===true?'__done':id,b=k==='__done'?S.done:(S.all||[]).find(x=>x.id===k);if(!b)return;const r=rcd(b),m=document.createElement('div');m.id='md';m.className='md';m.innerHTML=`<div class="mb" style="max-width:460px;background:#fff;color:#0b1b4a"><div id="rcv" style="font-family:Outfit,Arial,sans-serif"><img src="${LG.l}" style="height:46px"><div style="display:flex;justify-content:space-between;margin:14px 0 6px"><b style="font-size:20px">Recibo ${r.f}</b><span style="color:#6b7aa6">${b.date}</span></div><div style="border-top:1px dashed #c8d6f3;padding:10px 0;line-height:1.7"><div><span style="color:#6b7aa6">Cliente</span> · ${esc(b.name)}</div><div><span style="color:#6b7aa6">Placa</span> · ${esc(b.placa||'—')} · ${esc(b.moto||'')}</div><div><span style="color:#6b7aa6">Cita</span> · ${lab(b.start)} con ${esc(sName(b.staff))}</div></div><div style="border-top:1px dashed #c8d6f3;padding:10px 0">${r.it.map(x=>`<div style="display:flex;justify-content:space-between;padding:2px 0"><span>${esc(x[0])}</span><b>${COP(x[1])}</b></div>`).join('')}${r.disc?`<div style="display:flex;justify-content:space-between;color:#0f8a5f"><span>Descuentos</span><b>-${COP(r.disc)}</b></div>`:''}</div><div style="display:flex;justify-content:space-between;border-top:2px solid #0b1b4a;padding-top:10px;font-size:22px"><b>Total</b><b style="color:#1951fc">${COP(b.total)}</b></div><p style="color:#6b7aa6;font-size:13px;line-height:1.5">${esc(r.pay)}<br>⏱ Tienes 10 minutos de tolerancia para llegar a tu cita.${cfg.set.addr?'<br>📍 '+esc(cfg.set.addr):''}</p></div><div style="display:flex;gap:8px;margin-top:10px;flex-wrap:wrap"><button class="btn" onclick="rcpSave('${k}')">⬇ Descargar recibo</button><button class="btn g" onclick="document.getElementById('md').remove()">Cerrar</button></div></div>`;document.body.appendChild(m)};
async function rcpBlob(b){const r=rcd(b),W=700,H=600+(r.it.length+(r.disc?1:0))*42,c=document.createElement('canvas');c.width=W;c.height=H;const x=c.getContext('2d'),FN='Outfit,Arial,sans-serif';x.fillStyle='#fff';x.fillRect(0,0,W,H);const im=await new Promise(res=>{const i=new Image();i.onload=()=>res(i);i.onerror=()=>res(null);i.src=LG.l});if(im){const h=72;x.drawImage(im,40,32,im.width/im.height*h,h)}const T=(s,px,py,f,col,al)=>{x.font=f;x.fillStyle=col||'#0b1b4a';x.textAlign=al||'left';x.fillText(s,px,py)},L=(py,d)=>{x.strokeStyle=d?'#c8d6f3':'#0b1b4a';x.lineWidth=d?2:3;x.setLineDash(d?[8,6]:[]);x.beginPath();x.moveTo(40,py);x.lineTo(W-40,py);x.stroke();x.setLineDash([])};let y=170;T('Recibo '+r.f,40,y,'700 32px '+FN);T(b.date,W-40,y,'400 24px '+FN,'#6b7aa6','right');y+=22;L(y,1);y+=40;[['Cliente',b.name],['Placa',b.placa||'—'],['Moto',b.moto||'—'],['Cita',lab(b.start)+' con '+sName(b.staff)]].forEach(p=>{T(p[0],40,y,'400 22px '+FN,'#6b7aa6');T(p[1],W-40,y,'600 22px '+FN,null,'right');y+=38});y-=10;L(y,1);y+=42;r.it.forEach(p=>{T(p[0],40,y,'500 23px '+FN);T(COP(p[1]),W-40,y,'600 23px '+FN,null,'right');y+=42});if(r.disc){T('Descuentos',40,y,'500 23px '+FN,'#0f8a5f');T('-'+COP(r.disc),W-40,y,'600 23px '+FN,'#0f8a5f','right');y+=42}y-=14;L(y);y+=48;T('Total',40,y,'700 32px '+FN);T(COP(b.total),W-40,y,'700 36px '+FN,'#1951fc','right');y+=46;T(r.pay,40,y,'500 22px '+FN,'#6b7aa6');y+=36;T('Tienes 10 minutos de tolerancia para llegar a tu cita.',40,y,'400 20px '+FN,'#6b7aa6');if(cfg.set.addr){y+=32;T(cfg.set.addr,40,y,'400 20px '+FN,'#6b7aa6')}return new Promise(res=>c.toBlob(res,'image/png'))}
window.rcpSave=async k=>{const b=k==='__done'?S.done:(S.all||[]).find(x=>x.id===k);if(!b)return;const dl=await claude.use('downloads');if(!dl)return toast('⚠️ La descarga no está disponible en este momento');const f='recibo-'+b.id.slice(-5).toUpperCase();try{await dl.save({filename:f+'.png',data:await rcpBlob(b)});toast('✅ Recibo descargado')}catch(e){if(e&&e.code==='declined')return;try{await dl.save({filename:f+'.html',data:'<!doctype html><meta charset="utf-8"><title>Recibo</title><body style="max-width:480px;margin:24px auto">'+document.getElementById('rcv').innerHTML+'</body>'});toast('✅ Recibo descargado')}catch(e2){toast('⚠️ '+((e2&&e2.message)||'No se pudo descargar'))}}};
async function moveBook(id,to,i){const b=(S.all||[]).find(x=>x.id===id);if(!b||!db)return;i=Math.max(0,Math.min(N-b.n,i));if(b.staff===to&&b.start===i)return;const bz=await busy(b.date,id);for(let k=0;k<b.n;k++)if(bz.has(to+'_'+(i+k)))return toast('⚠️ Ese horario ya está ocupado para '+sName(to));await place(b,to,i,{});toast('✅ Cita movida a las '+lab(i)+' con '+sName(to))}
window.evDown=(e,id)=>{if(e.button>0)return;const el=e.currentTarget,x0=e.clientX,y0=e.clientY,r=el.getBoundingClientRect(),dx=x0-r.left,dy=y0-r.top;let drag=false,g=null,hot=null;const mv=ev=>{if(!drag){if(Math.hypot(ev.clientX-x0,ev.clientY-y0)<6||S.ag.v!=='d')return;drag=true;S.drag=id;g=el.cloneNode(true);g.style.cssText=`position:fixed;left:${r.left}px;top:${r.top}px;width:${r.width}px;height:${r.height}px;z-index:60;pointer-events:none;opacity:.92;box-shadow:0 18px 40px #03195b55`;document.body.appendChild(g);el.style.opacity='.25'}g.style.left=ev.clientX-dx+'px';g.style.top=ev.clientY-dy+'px';const t=document.elementFromPoint(ev.clientX,ev.clientY),c=t&&t.closest('.dc[data-s]');if(hot!==c){hot&&hot.classList.remove('hot');hot=c;hot&&hot.classList.add('hot')}},up=async ev=>{removeEventListener('pointermove',mv);removeEventListener('pointerup',up);removeEventListener('pointercancel',up);if(!drag){evOpen(id);return}g.remove();el.style.opacity='';const c=hot;hot&&hot.classList.remove('hot');S.drag=null;if(c)await moveBook(id,c.dataset.s,Math.round((ev.clientY-dy-c.getBoundingClientRect().top)/RH));render()};addEventListener('pointermove',mv);addEventListener('pointerup',up);addEventListener('pointercancel',up)};
window.evOpen=id=>{const m=document.createElement('div');m.id='md';m.className='md';m.innerHTML=`<div class="mb" id="evm" data-id="${id}" style="max-width:560px"></div>`;document.body.appendChild(m);evFill(id)};
