function evFill(id){const b=(S.all||[]).find(x=>x.id===id),el=document.getElementById('evm');if(!el)return;if(!b){const m=document.getElementById('md');if(m)m.remove();return}const c=sg(b);el.innerHTML=`<div class="jh"><h3 style="font-size:28px">${lab(b.start)}–${lab(b.start+b.n)} · ${esc(b.name)}</h3><span class="pl p${c<0?0:c>=7?2:1}">${c<0?'Pendiente':c>=7?'Lista':STG[c][0]}</span></div><p class="empty">🔖 ${esc(b.placa||'—')} · 🏍️ ${esc(b.moto||'—')} · 📞 ${esc(b.phone||'—')}<br>${b.date} · ${esc(sName(b.staff))}</p><p>${b.svc.map(esc).join(', ')} · <b>${COP(b.total)}</b> ${b.pay==='ok'?'<span class="badge ok">✅ '+esc(b.pm||'Pagado')+'</span>':''}</p>${b.note?`<div class="note">📝 ${esc(b.note)}</div>`:''}${stepper(b,true)}<div class="acts" style="margin-top:12px">${c<7?`<span onclick="setStg('${id}',${c+1})" style="background:var(--ac2)!important;color:#fff!important;font-weight:700">${c<0?'Iniciar lavado':'Siguiente: '+STG[c+1][0]} →</span>`:''}${c<0?`<span onclick="lateB('${id}')">⏰ Llegó tarde</span>`:''}${b.pay==='ok'?'':`<span onclick="evAct('payB','${id}')">💰 Cobrar</span>`}<span onclick="evAct('sendRcp','${id}')">🧾 Recibo</span><span onclick="evAct('editB','${id}')">✏️ Editar</span><span onclick="delB('${id}')" style="color:#d6334b!important">🗑 Eliminar</span></div><div style="margin-top:14px"><button class="btn g" onclick="document.getElementById('md').remove()">Cerrar</button></div>`}
