function miniCal(){const A=S.ag,d=pd(A.d),y=d.getFullYear(),m=d.getMonth(),off=(new Date(y,m,1).getDay()+6)%7,dim=new Date(y,m+1,0).getDate(),has=new Set((S.all||[]).filter(b=>!b.wait).map(b=>b.date)),w0=ymd(wk0(A.d)),w1=ymd(new Date(wk0(A.d).getTime()+6*864e5)),t=ymd(new Date());let c='';for(let i=0;i<off;i++)c+='<span></span>';for(let i=1;i<=dim;i++){const s=ymd(new Date(y,m,i));c+=`<button class="dy ${s===A.d?'sel':''} ${A.v==='w'&&s>=w0&&s<=w1?'inw':''} ${s===t?'td':''}" onclick="agSet('${s}')">${i}${has.has(s)?'<i></i>':''}</button>`}return `<div class="pn"><div class="jh" style="align-items:center;margin-bottom:8px"><b style="text-transform:capitalize">${MES[m]} ${y}</b><span><button class="pill" onclick="agM(-1)">‹</button> <button class="pill" onclick="agM(1)">›</button></span></div><div class="m7 mh">${['L','M','M','J','V','S','D'].map(x=>`<span>${x}</span>`).join('')}</div><div class="m7">${c}</div></div>`}
