function resHtml(){const all=(S.all||[]).filter(b=>!b.wait),t=ymd(new Date()),y=ymd(new Date(Date.now()-864e5)),td=all.filter(b=>b.date===t).sort((a,c)=>a.start-c.start),yd=all.filter(b=>b.date===y),sm=a=>a.reduce((s,x)=>s+x.total,0),proc=td.filter(b=>sg(b)>=0&&sg(b)<7),don=td.filter(b=>sg(b)>=7),cob=td.filter(b=>b.pay!=='ok'),dl=(a,b)=>b?`<span class="dl ${a>=b?'':'dn'}">${a>=b?'▲':'▼'} ${Math.abs(Math.round((a-b)/b*100))}% vs ayer</span>`:'',d7=[...Array(7)].map((_,i)=>ymd(new Date(Date.now()-(6-i)*864e5))),v7=d7.map(d=>sm(all.filter(b=>b.date===d))),mx=Math.max(1,...v7),line=v7.map((v,i)=>(i?'L':'M')+(10+i*280/6).toFixed(1)+' '+(88-v/mx*68).toFixed(1)).join(' '),lim=ymd(new Date(Date.now()-30*864e5)),sv={};all.filter(b=>b.date>=lim).forEach(b=>b.svc.forEach(n=>sv[n]=(sv[n]||0)+1));const tt=Object.values(sv).reduce((a,b)=>a+b,0)||1,top=Object.entries(sv).sort((a,b)=>b[1]-a[1]).slice(0,4),np=td.length-proc.length-don.length,ts=td.length||1,a1=np/ts*100,a2=a1+proc.length/ts*100,rec=[...(S.all||[])].filter(b=>b.created).sort((a,c)=>c.created-a.created).slice(0,5);return `<div class="g4"><div class="sc"><div class="ic2">🗓</div><div><small>Citas hoy</small><b>${td.length}</b>${dl(td.length,yd.length)}</div></div><div class="sc"><div class="ic2">💵</div><div><small>Ingresos hoy</small><b>${COP(sm(td))}</b>${dl(sm(td),sm(yd))}</div></div><div class="sc"><div class="ic2">🧽</div><div><small>En proceso</small><b>${proc.length}</b></div></div><div class="sc"><div class="ic2">⏳</div><div><small>Por cobrar (${cob.length})</small><b>${COP(sm(cob))}</b></div></div></div><div class="dg"><div class="pn"><div class="jh" style="align-items:center;margin-bottom:8px"><h3>Citas de hoy</h3><span class="pill" style="cursor:pointer" onclick="S.tab='ag';render()">Ver agenda →</span></div><div class="tw"><table class="tbl"><thead><tr><th>Hora</th><th>Cliente</th><th>Servicios</th><th>Atiende</th><th>Estado</th><th>Total</th></tr></thead><tbody>${td.length?td.map(b=>{const c=sg(b);return `<tr onclick="evOpen('${b.id}')"><td><b>${lab(b.start)}</b></td><td>${esc(b.name)}<br><small>${esc(b.placa||'—')}</small></td><td>${b.svc.map(esc).join(', ')}</td><td>${esc(sName(b.staff))}</td><td><span class="pl p${c<0?0:c>=7?2:1}">${c<0?'Pendiente':c>=7?'Lista':STG[c][0]}</span></td><td>${COP(b.total)} ${b.pay==='ok'?'✅':''}</td></tr>`}).join(''):'<tr><td colspan="6" class="empty">Hoy no hay citas.</td></tr>'}</tbody></table></div></div><div style="display:grid;gap:14px;align-content:start"><div class="pn"><h3>Acciones rápidas</h3><div class="qa" onclick="walkin()"><i>➕</i><div><b>Nueva cita</b><small>Agendar o walk-in</small></div></div><div class="qa" onclick="S.tab='caja';S.cd=ymd(new Date());render()"><i>💵</i><div><b>Cobrar y cerrar caja</b><small>${cob.length} por cobrar hoy</small></div></div><div class="qa" onclick="S.tab='his';render()"><i>🧾</i><div><b>Historial y recibos</b><small>Pagos y servicios</small></div></div></div><div class="pn"><h3>Ventas · 7 días</h3><b class="big">${COP(v7.reduce((a,b)=>a+b,0))}</b><svg viewBox="0 0 300 100" style="width:100%;height:100px"><defs><linearGradient id="gA" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#3781fc" stop-opacity=".35"/><stop offset="1" stop-color="#3781fc" stop-opacity="0"/></linearGradient></defs><path d="${line} L290 95 L10 95 Z" fill="url(#gA)"/><path d="${line}" fill="none" stroke="#1951fc" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg></div><div class="pn"><h3>Servicios top · 30 días</h3>${top.length?top.map(([k,v])=>`<div class="br"><span>${esc(k)}</span><div class="bw"><i style="width:${v/tt*100}%"></i></div><em>${Math.round(v/tt*100)}%</em></div>`).join(''):'<p class="empty">Sin datos todavía.</p>'}</div></div></div><div class="dg2"><div class="pn"><h3>Estado de hoy</h3><div class="dnw"><div class="dn2" style="background:conic-gradient(#cbd6ee 0 ${a1}%,#3781fc ${a1}% ${a2}%,#1ec28b ${a2}% 100%)"><b>${td.length}</b></div><div><div class="lgd"><i style="background:#cbd6ee"></i>Pendientes · ${np}</div><div class="lgd"><i style="background:#3781fc"></i>En proceso · ${proc.length}</div><div class="lgd"><i style="background:#1ec28b"></i>Listas · ${don.length}</div></div></div></div><div class="pn"><h3>Actividad reciente</h3>${rec.length?rec.map(b=>`<div class="act"><i>📅</i><span><b>${esc(b.name.split(' ')[0])}</b> ${b.walk?'llegó sin cita':'agendó'} ${b.svc.length>1?b.svc.length+' servicios':esc(b.svc[0]||'')}</span><small>${ago(b.created)}</small></div>`).join(''):'<p class="empty">Sin actividad todavía.</p>'}</div></div>`}
function preciosHtml(){return `<div class="cd"><p class="empty">Los cambios se guardan solos y se ven al instante en la página de clientes.</p><div class="row" style="font-size:12px;color:#6b7aa6"><span>Servicio</span><span>Precio (COP)</span><span>Minutos</span><span></span></div>${cfg.services.map((s,i)=>`<div class="row"><input value="${esc(s.name)}" onchange="up(${i},'name',this.value)"><input type="number" value="${s.price}" onchange="up(${i},'price',+this.value)"><input type="number" value="${s.min}" onchange="up(${i},'min',+this.value)"><button class="btn r" onclick="rm(${i})">✕</button></div>`).join('')}<button class="btn g" onclick="addS()">+ Nuevo servicio</button></div>`}
window.rm=async i=>{if(await ask('¿Eliminar el servicio <b>'+esc(cfg.services[i].name)+'</b>?','Sí, eliminar')){cfg.services.splice(i,1);saveCfg();render()}};
const ADM=[['res','Resumen','▦'],['ag','Agenda','🗓'],['taller','Lavados','🧽'],['caja','Caja','💵'],['cli','Clientes','👥'],['rep','Reportes','📊'],['his','Historial','🧾'],null,['precios','Precios','🏷'],['equipo','Equipo','🛠'],['bloq','Bloqueos','⛔'],['link','Accesos','🔗'],['aj','Ajustes','⚙']],TT={res:['Resumen','Lo que pasa hoy en el taller'],ag:['Agenda','Citas por día y por persona'],taller:['Lavados','Etapas del lavado y lista de espera'],caja:['Caja','Cobros y cierre del día'],cli:['Clientes','Historial y descuentos'],rep:['Reportes','Cómo va el negocio'],his:['Historial','Pagos y servicios'],precios:['Precios','Servicios y tiempos'],equipo:['Equipo','Empleados y accesos'],bloq:['Bloqueos','Horas no disponibles'],link:['Accesos','Links para compartir'],aj:['Ajustes','Datos del negocio']};
function admBody(){switch(S.tab){case'ag':return agHtml();case'taller':return tallerHtml();case'caja':return cajaHtml();case'cli':return clientsHtml();case'rep':return repHtml();case'his':return hisHtml();case'precios':return preciosHtml();case'equipo':return equipoHtml();case'bloq':return bloqHtml();case'link':return linksHtml();case'aj':return ajHtml();default:return resHtml()}}
renderAdmin=function(a,bar){bar.hidden=true;if(!(S.auth&&S.auth.role==='admin')){a.innerHTML=head()+loginHtml('admin');return}const tt=TT[S.tab]||TT.res,hr=new Date().getHours();a.innerHTML=`<div class="shell"><aside class="sb"><div class="sbl"><img src="${LG.l}" alt="Spa Motos 20IVI"></div><nav>${ADM.map(t=>t?`<button class="ni ${S.tab===t[0]?'on':''}" onclick="S.tab='${t[0]}';render()"><i>${t[2]}</i><span>${t[1]}</span></button>`:'<hr>').join('')}</nav><div class="sbu"><button class="ni" onclick="location.hash='';render()"><i>↩</i><span>Ver como cliente</span></button><button class="ni" onclick="logout()"><i>⎋</i><span>Salir</span></button></div></aside><main class="mn"><div class="tb"><div><h1>${S.tab==='res'||!TT[S.tab]?(hr<12?'Buenos días':hr<19?'Buenas tardes':'Buenas noches')+', '+esc((window.PROFILE&&PROFILE.username)||'Admin'):tt[0]}</h1><p>${tt[1]}</p></div><button class="btn" onclick="walkin()">+ Nueva cita</button></div>${admBody()}</main></div>`};
const _rd4=render;render=function(){document.body.classList.toggle('adm',!!(isAdminView()&&S.auth&&S.auth.role==='admin'));_rd4();const e=document.getElementById('evm');if(e)evFill(e.dataset.id)};
window.tg=id=>{S.sel.has(id)?S.sel.delete(id):S.sel.add(id);S.slot=null;render()};
window.sd=d=>{S.date=d;S.slot=null;watchSlots();render()};
window.sp=id=>{S.staff=id;S.slot=null;render()};
window.ss=i=>{S.slot=i;render()};
$('#next').onclick=()=>{if(S.step===2)return confirmBooking();S.step++;scrollTo({top:0,behavior:'smooth'});render()};
$('#back').onclick=()=>{S.step--;render()};
function renderAdmin(a,bar){bar.hidden=true;
 if(!isAdmin){a.innerHTML=head()+'<p class="empty">Solo el administrador puede ver este panel.</p>';return}
 const tabs=[['agenda','📅 Agenda'],['precios','💰 Precios'],['bloq','⛔ Bloqueos'],['aj','⚙ Ajustes'],['equipo','👥 Equipo']];
 let h=head()+`<h1 style="font-size:56px">Panel <span style="color:var(--ac)">admin</span></h1><div class="tabs">${tabs.map(t=>`<button class="tab ${S.tab===t[0]?'on':''}" onclick="S.tab='${t[0]}';render()">${t[1]}</button>`).join('')}</div>`;
 if(S.tab==='agenda'){const bs=S.books||[];
  h+=`<div class="chips">${days.map(d=>`<div class="chip ${ymd(d)===S.adate?'on':''}" onclick="S.adate=S.date='${ymd(d)}';watchSlots();watchBooks()"><small>${DN[d.getDay()]}</small><b>${d.getDate()}</b></div>`).join('')}</div>`;
  if(S.books===null)h+='<div class="note">No se pudieron leer las citas. Revisa los permisos del artefacto.</div>';
  h+=`<button class="btn g" onclick="manual()" style="margin-bottom:12px">+ Cita manual</button> <button class="btn r" onclick="clearDay()" style="margin-bottom:12px">🗑 Eliminar todas las del día</button><div class="stats"><div class="stat"><b>${bs.length}</b><small>citas del día</small></div><div class="stat"><b>${COP(bs.reduce((a,b)=>a+b.total,0))}</b><small>ingreso estimado</small></div><div class="stat"><b>${COP((S.all||[]).filter(b=>b.date>=ymd(days[0])&&b.date<=ymd(days[6])).reduce((a,b)=>a+b.total,0))}</b><small>próx. 7 días</small></div></div><div class="cols">${cfg.staff.map(p=>{const m=bs.filter(b=>b.staff===p.id);return `<div class="col" data-s="${p.id}"><h3>${esc(p.name)}</h3>${m.length?m.map(b=>`<div class="ap"><div class="gr" onpointerdown="dragStart(event,'${b.id}')" title="Arrastra para cambiar de persona">⠿</div><b>${lab(b.start)} – ${lab(b.start+b.n)}</b> · ${esc(b.name)}<small>📞 ${esc(b.phone)} · 🏍️ ${esc(b.moto||'—')}</small><small>${b.svc.map(esc).join(', ')}</small>${b.note?`<small>📝 ${esc(b.note)}</small>`:''}<div style="display:flex;justify-content:space-between;align-items:center;margin-top:6px"><b style="color:var(--ac)">${COP(b.total)}</b><button class="btn g" style="padding:8px 10px;font-size:12px" onclick="stNext('${b.id}','${NX[b.st||'pend']}')">${LB[b.st||'pend']}</button><button class="btn g" style="padding:8px 10px;font-size:12px" onclick="editB('${b.id}')">✏️ Editar</button><button class="btn g" style="padding:8px 10px;font-size:12px" onclick="detB('${b.id}')">🔎</button><button class="btn r" onclick='cancelBooking(${JSON.stringify(b).replace(/'/g,"&#39;")})'>Cancelar</button></div></div>`).join(''):'<div class="empty">Sin citas</div>'}</div>`}).join('')}</div>`}
 if(S.tab==='precios')h+=`<p class="empty">Los cambios se guardan solos y se ven al instante en la página de clientes.</p>${cfg.services.map((s,i)=>`<div class="row"><input value="${esc(s.name)}" onchange="up(${i},'name',this.value)"><input type="number" value="${s.price}" onchange="up(${i},'price',+this.value)"><input type="number" value="${s.min}" onchange="up(${i},'min',+this.value)"><button class="btn r" onclick="rm(${i})">✕</button></div>`).join('')}<button class="btn g" onclick="addS()">+ Nuevo servicio</button><p class="empty">Columnas: nombre · precio (COP) · minutos.</p>`;
 if(S.tab==='bloq')h+=bloqHtml();if(S.tab==='aj')h+=ajHtml();
 if(S.tab==='equipo')h+=cfg.staff.map((p,i)=>`<div class="row s"><input value="${esc(p.name)}" onchange="cfg.staff[${i}].name=this.value;saveCfg()"><button class="btn r" onclick="cfg.staff.splice(${i},1);saveCfg();render()">✕</button></div>`).join('')+`<button class="btn g" onclick="cfg.staff.push({id:'s'+Date.now(),name:'Nuevo'});saveCfg();render()">+ Agregar persona de lavado</button>`;
 a.innerHTML=h;}
window.up=(i,k,v)=>{cfg.services[i][k]=v;saveCfg()};
window.rm=i=>{if(confirm('¿Eliminar este servicio?')){cfg.services.splice(i,1);saveCfg();render()}};
window.addS=()=>{cfg.services.push({id:'n'+Date.now(),ic:'🏍️',name:'Nuevo servicio',d:'',price:10000,min:30});saveCfg();render()};
window.cancelBooking=cancelBooking;window.S=S;window.render=render;window.watchBooks=watchBooks;
addEventListener('hashchange',()=>{if(isAdminView())watchBooks();else watchSlots();render()});
render();
(async()=>{try{user=await claude.use('user');isAdmin=user?user.canEdit():false;db=await claude.use('db')}catch(e){}
 if(db){db.collection('config').doc('main').onSnapshot(s=>{if(s.exists){const d=s.data();if(d.services)cfg={set:DEF.set,combos:DEF.combos,pm:DEF.pm,...JSON.parse(JSON.stringify(d))};S.sel=new Set([...S.sel].filter(id=>cfg.services.some(x=>x.id===id)));if(!isAdminView()||S.tab==='agenda')render()}},()=>{});watchSlots();if(isAdmin)watchBooks()}
 render();})();
